@@ -0,0 +1,11 @@
+export function retryDelayMs(attempt: number): number {
+  // Full jitter (not equal jitter): spreads synchronized client retries,
+  // which equal jitter only halves.
+  const cap = Math.min(30_000, 1_000 * 2 ** attempt);
+  return Math.random() * cap;
+}
+
+export function normalizeSku(raw: string): string {
+  // Legacy SKUs mix en-dash and hyphen; the warehouse API accepts only hyphen.
+  return raw.trim().replace(/–/g, "-").toUpperCase();
+}
